mapper.select:
SELECT a.id, a.helmet_id, a.helmet_type, a.battery_level, a.ip, a.mac_address, a.assigned_person, a.assigned_workshop, a.assigned_process, a.assigned_team, a.motion_status, a.create_by, a.create_date, a.update_by, a.update_date, a.remarks FROM swm_helmet_device a
AND a.helmet_id = #{helmetId}
AND a.helmet_type = #{helmetType}
AND a.assigned_person = #{assignedPerson}
AND a.assigned_workshop = #{assignedWorkshop}
AND a.assigned_process = #{assignedProcess}
AND a.assigned_team = #{assignedTeam}
ORDER BY a.update_date DESC
